#include <algorithm>
#include <chrono>
#include <cmath>
#include <iostream>
#include <string>
#include <vector>
#include "vendor/json.hpp"
using json=nlohmann::json;
using Clock=std::chrono::steady_clock;
static long long ns(Clock::time_point t){return std::chrono::duration_cast<std::chrono::nanoseconds>(t.time_since_epoch()).count();}
static double median(std::vector<double> v){v.erase(std::remove_if(v.begin(),v.end(),[](double x){return !std::isfinite(x)||x<=0;}),v.end());for(auto &x:v)x=std::round(x);if(v.empty())return 0;std::sort(v.begin(),v.end());size_t m=v.size()/2;return v.size()%2?v[m]:std::floor((v[m-1]+v[m])/2);}
static double num(const json& j,const char* k,double d=0){try{return j.at(k).get<double>();}catch(...){return d;}}
static std::string str(const json& j,const char* k,std::string d=""){try{return j.at(k).get<std::string>();}catch(...){return d;}}
static json evaluate(const json& in,long long parseNs){auto t0=Clock::now();auto l=in.value("listing",json::object()),p=in.value("policy",json::object());auto history=in.value("history",std::vector<double>{}),book=in.value("book",std::vector<double>{});double fair=median(history);auto t1=Clock::now();std::vector<double> filtered;for(double x:history)if(std::isfinite(x)&&fair>0&&x>=fair*.65&&x<=fair*1.35)filtered.push_back(x);double market=median(book),anchor=filtered.empty()?fair:median(filtered),reference=market?std::min(anchor?anchor:market,market):anchor;double price=num(l,"price"),fast=std::max(0.0,std::floor(reference*.9)),fee=std::max(0.0,num(p,"feePct")),profit=std::floor(fast*(100-fee)/100-price),roi=price>0?profit/price*100:0;double histScore=std::min(60.0,filtered.size()*6.0),bookScore=std::min(25.0,book.size()*5.0),spreadScore=market&&reference?std::max(0.0,15.0-std::floor(std::abs(market-reference)/reference*100)):0;int liquidity=(int)std::max(0.0,std::min(100.0,histScore+bookScore+spreadScore));auto t2=Clock::now();std::string reason;auto id=str(l,"listingId"),asset=str(l,"assetId");double at=num(l,"at"),now=num(in,"now"),maxAge=num(p,"maxBookAgeMs"),maxPrice=num(p,"maxPrice"),minProfit=num(p,"minProfit"),minRoi=num(p,"minRoiPct"),minHist=num(p,"minHistory"),minLiq=num(p,"minLiquidity"),minMargin=num(p,"minMarginPct");if(id.empty()||asset.empty()||!std::isfinite(price)||price<=0)reason="listing-invalid";else if(now-at>maxAge)reason="listing-stale";else if(history.size()<minHist||filtered.size()<minHist)reason="insufficient-history";else if(!market||book.empty())reason="insufficient-live-book";else if(price>maxPrice)reason="above-max-price";else if(liquidity<minLiq)reason="low-liquidity";else if(profit<minProfit)reason="profit-below-minimum";else if(roi<minRoi)reason="roi-below-minimum";else if(fast<=price*(1+minMargin/100))reason="margin-below-minimum";auto t3=Clock::now();auto t4=Clock::now();return json{{"engine","cpp"},{"eventId",str(in,"eventId")},{"decision",reason.empty()?"BUY":"IGNORE"},{"reason",reason.empty()?"risk-checks-passed":reason},{"fairValue",reference},{"fastSell",fast},{"liquidity",liquidity},{"profit",profit},{"roiPct",std::floor(roi*100)/100},{"historyCount",filtered.size()},{"parseNs",std::to_string(parseNs)},{"filterNs",std::to_string(ns(t2)-ns(t1))},{"strategyNs",std::to_string(ns(t3)-ns(t2))},{"decisionNs",std::to_string(parseNs+ns(t4)-ns(t0))}};}
int main(){std::string line;while(std::getline(std::cin,line)){try{auto start=Clock::now();auto in=json::parse(line);auto elapsed=ns(Clock::now())-ns(start);std::cout<<evaluate(in,elapsed).dump()<<std::endl;}catch(const std::exception& e){std::cout<<json{{"engine","cpp"},{"eventId",""},{"decision","IGNORE"},{"reason","engine-error"},{"error",e.what()}}.dump()<<std::endl;}}}
